    privacyShort: "Confidentialité",
    termsShort: "Conditions",
    lastUpdated: "Mise à jour :",
    faqSecWallet: "Portefeuille",
    faqSecDapps: "dApps",
    faqQ1: "Comment créer un wallet ?",
    faqA1:
      "Sur l’écran de bienvenue, appuie sur « Créer un wallet ». Kalyx génère une phrase de récupération de 12 mots que tu dois noter sur papier, puis tu vérifies quelques mots et tu choisis un code PIN. Tes clés sont créées directement sur ton téléphone.",
    faqQ2: "Comment restaurer un wallet ?",
    faqA2:
      "Sur l’écran de bienvenue, appuie sur « J’ai déjà une phrase », colle ta phrase de récupération BIP-39 (12 ou 24 mots) et choisis un PIN. Ton wallet et ses comptes sont redérivés localement.",
    faqQ3: "Où est stockée ma phrase secrète ?",
    faqA3:
      "Uniquement sur ton téléphone, chiffrée en AES-256-GCM sous ton PIN, dans le stockage sécurisé matériel (Keystore/Keychain). Elle n’est JAMAIS envoyée sur le réseau ni stockée sur un serveur.",
    faqQ4: "Puis-je changer mon PIN ?",
    faqA4:
      "Oui : Réglages → Changer le PIN. Le changement re-chiffre tous tes coffres avec le nouveau code.",
    faqQ5: "Que faire si je perds mon téléphone ?",
    faqA5:
      "Tes fonds sont sur la blockchain, pas dans le téléphone. Installe Kalyx sur un nouvel appareil et restaure avec ta phrase de récupération. Sans cette phrase, personne (toi inclus) ne peut accéder aux fonds — d’où l’importance de la garder en lieu sûr.",
    faqQ6: "Kalyx peut-il voir ma seed phrase ?",
    faqA6:
      "Non. Kalyx est non-custodial : ta phrase est chiffrée sur ton appareil, déchiffrée à la volée uniquement pour signer, puis oubliée. Elle ne transite jamais par nos serveurs.",
    faqQ7: "Pourquoi dois-je signer certaines transactions ?",
    faqA7:
      "Toute action qui déplace des fonds ou autorise un contrat à les dépenser doit être signée par ta clé privée, protégée par ton PIN. C’est ce qui empêche un site de faire quoi que ce soit sans ton accord explicite.",
    faqQ8: "Comment reconnaître une arnaque ?",
    faqA8:
      "Personne de légitime ne te demandera jamais ta phrase de récupération. Méfie-toi des sites qui imitent une marque connue (Kalyx t’alerte en rouge), des approbations « illimitées », et des messages trop beaux pour être vrais. Kalyx affiche aussi une analyse de sécurité (GoPlus) avant chaque signature.",
    faqQ9: "Pourquoi ma transaction est-elle en attente ?",
    faqA9:
      "Elle attend d’être incluse dans un bloc. Des frais de réseau trop bas ou une forte congestion la ralentissent. Kalyx te notifie dès qu’elle est confirmée.",
    faqQ10: "Comment annuler une transaction ?",
    faqA10:
      "Une transaction confirmée est irréversible. Une transaction encore en attente peut parfois être remplacée (même nonce, frais plus élevés) — cette fonction n’est pas encore automatisée dans Kalyx.",
    faqQ11: "Que sont les frais de réseau ?",
    faqA11:
      "C’est le coût payé aux validateurs du réseau pour traiter ta transaction, réglé dans la crypto native (ETH, BNB, POL…). Il varie selon la congestion du réseau.",
    faqQ12: "Pourquoi ma transaction a-t-elle échoué ?",
    faqA12:
      "Causes fréquentes : solde insuffisant (frais compris), slippage dépassé sur un swap, limite de gas trop basse, ou le contrat a rejeté l’opération. Note : les frais de gas d’une transaction échouée sont quand même prélevés.",
    faqQ13: "Comment connecter une dApp ?",
    faqA13:
      "Deux façons : le navigateur intégré (Menu → Navigateur dApps), ou WalletConnect (colle le lien « wc:… »). Dans les deux cas, tu confirmes la connexion avec ton PIN.",
    faqQ14: "Comment déconnecter une dApp ?",
    faqA14:
      "Onglet WalletConnect : « Déconnecter » pour une session WalletConnect, « Oublier » pour un site du navigateur intégré.",
    faqQ15: "Qu’est-ce que WalletConnect ?",
    faqA15:
      "Un protocole standard qui relie ton wallet à une dApp via un QR code ou un lien, sans extension de navigateur.",
    faqQ16: "Comment révoquer une autorisation ?",
    faqA16:
      "Menu → Approbations : Kalyx liste les contrats que tu as autorisés à dépenser tes tokens. Révoque ceux que tu n’utilises plus (c’est une transaction, avec frais de réseau).",
    faqQ17: "Comment changer de réseau ?",
    faqA17:
      "Depuis l’accueil (le badge du réseau) ou Réglages → Réseau. La même adresse fonctionne sur tous les réseaux EVM ; seul le réseau interrogé change.",
    faqQ18: "Comment ajouter un réseau RPC ?",
    faqA18:
      "Active le Mode expert, puis Menu → Développeur → Réseaux personnalisés : renseigne le nom, le Chain ID, le symbole et l’URL du RPC (https).",
    authenticating: "Authentification…",
