    faqQ1: "Nasıl cüzdan oluştururum?",
    faqA1:
      "Karşılama ekranında “Cüzdan oluştur”a dokun. Kalyx, kâğıda yazman gereken 12 kelimelik bir kurtarma ifadesi oluşturur, ardından birkaç kelimeyi doğrular ve bir PIN seçersin. Anahtarların doğrudan telefonunda oluşturulur.",
    faqQ2: "Nasıl cüzdan geri yüklerim?",
    faqA2:
      "Karşılama ekranında “Zaten bir ifadem var”a dokun, BIP-39 kurtarma ifadeni (12 veya 24 kelime) yapıştır ve bir PIN seç. Cüzdanın ve hesapları yerel olarak yeniden türetilir.",
    faqQ3: "Gizli ifadem nerede saklanır?",
    faqA3:
      "Yalnızca telefonunda, PIN’in altında AES-256-GCM ile şifrelenmiş olarak, donanım tabanlı güvenli depoda (Keystore/Keychain). ASLA ağ üzerinden gönderilmez veya bir sunucuda saklanmaz.",
    faqQ4: "PIN’imi değiştirebilir miyim?",
    faqA4:
      "Evet: Ayarlar → PIN değiştir. Değişiklik tüm kasalarını yeni kodla yeniden şifreler.",
    faqQ5: "Telefonumu kaybedersem ne olur?",
    faqA5:
      "Fonların telefonda değil, blok zincirinde. Kalyx’i yeni bir cihaza kur ve kurtarma ifadenle geri yükle. Bu ifade olmadan hiç kimse (sen dahil) fonlara erişemez — bu yüzden onu güvende tutmak önemlidir.",
    faqQ6: "Kalyx seed ifademi görebilir mi?",
    faqA6:
      "Hayır. Kalyx saklama gerektirmez: ifaden cihazında şifrelenir, yalnızca imzalamak için anlık olarak çözülür, sonra unutulur. Sunucularımızdan asla geçmez.",
    faqQ7: "Bazı işlemleri neden imzalamalıyım?",
    faqA7:
      "Fonları taşıyan veya bir kontratın onları harcamasına izin veren her eylem, PIN’inle korunan özel anahtarınla imzalanmalıdır. Bu, bir sitenin açık onayın olmadan hiçbir şey yapmasını engeller.",
    faqQ8: "Bir dolandırıcılığı nasıl tanırım?",
    faqA8:
      "Meşru hiç kimse asla kurtarma ifadeni istemez. Bilinen bir markayı taklit eden sitelere (Kalyx seni kırmızıyla uyarır), “sınırsız” onaylara ve gerçek olamayacak kadar iyi mesajlara dikkat et. Kalyx ayrıca her imzadan önce bir güvenlik analizi (GoPlus) gösterir.",
    faqQ9: "İşlemim neden beklemede?",
    faqA9:
      "Bir bloğa dahil edilmeyi bekliyor. Çok düşük ağ ücretleri veya yoğun tıkanıklık onu yavaşlatır. Kalyx, onaylandığı anda seni bilgilendirir.",
    faqQ10: "Bir işlemi nasıl iptal ederim?",
    faqA10:
      "Onaylanmış bir işlem geri alınamaz. Hâlâ bekleyen bir işlem bazen değiştirilebilir (aynı nonce, daha yüksek ücret) — bu özellik Kalyx’da henüz otomatik değil.",
    faqQ11: "Ağ ücretleri nedir?",
    faqA11:
      "İşlemini işlemek için ağ doğrulayıcılarına ödenen maliyettir, yerel kriptoda (ETH, BNB, POL…) ödenir. Ağ tıkanıklığına göre değişir.",
    faqQ12: "İşlemim neden başarısız oldu?",
    faqA12:
      "Sık nedenler: yetersiz bakiye (ücretler dahil), bir swapta aşılan slippage, çok düşük gas limiti veya kontratın işlemi reddetmesi. Not: başarısız bir işlemin gas ücretleri yine de alınır.",
    faqQ13: "Bir dApp’i nasıl bağlarım?",
    faqA13:
      "İki yol: yerleşik tarayıcı (Menü → dApp tarayıcısı) veya WalletConnect (“wc:…” bağlantısını yapıştır). Her iki durumda da bağlantıyı PIN’inle onaylarsın.",
    faqQ14: "Bir dApp’in bağlantısını nasıl keserim?",
    faqA14:
      "WalletConnect sekmesi: WalletConnect oturumu için “Bağlantıyı kes”, yerleşik tarayıcı sitesi için “Unut”.",
    faqQ15: "WalletConnect nedir?",
    faqA15:
      "Cüzdanını bir QR kodu veya bağlantı aracılığıyla, tarayıcı eklentisi olmadan bir dApp’e bağlayan standart bir protokol.",
    faqQ16: "Bir yetkilendirmeyi nasıl iptal ederim?",
    faqA16:
      "Menü → Onaylar: Kalyx, tokenlerini harcamasına izin verdiğin kontratları listeler. Artık kullanmadıklarını iptal et (bu bir işlemdir, ağ ücretleriyle).",
    faqQ17: "Ağı nasıl değiştiririm?",
    faqA17:
      "Ana ekrandan (ağ rozeti) veya Ayarlar → Ağ. Aynı adres tüm EVM ağlarında çalışır; yalnızca sorgulanan ağ değişir.",
    faqQ18: "RPC ağı nasıl eklerim?",
    faqA18:
      "Uzman modunu etkinleştir, sonra Menü → Geliştirici → Özel ağlar: adı, Chain ID’yi, sembolü ve RPC URL’sini (https) gir.",
