    lastUpdated: "更新于：",
    faqSecWallet: "钱包",
    faqSecDapps: "dApp",
    faqQ1: "如何创建钱包？",
    faqA1:
      "在欢迎界面点击“创建钱包”。Kalyx 生成 12 个词的恢复助记词，你需要抄写在纸上，然后验证几个词并选择一个 PIN。你的密钥直接在手机上创建。",
    faqQ2: "如何恢复钱包？",
    faqA2:
      "在欢迎界面点击“我已有助记词”，粘贴你的 BIP-39 恢复助记词（12 或 24 个词）并选择一个 PIN。你的钱包及其账户会在本地重新派生。",
    faqQ3: "我的助记词存储在哪里？",
    faqA3:
      "仅存储在你的手机上，用你的 PIN 以 AES-256-GCM 加密，保存在硬件安全存储（Keystore/Keychain）中。它绝不会通过网络发送或存储在服务器上。",
    faqQ4: "我可以更改 PIN 吗？",
    faqA4: "可以：设置 → 更改 PIN。更改会用新密码重新加密你所有的保险库。",
    faqQ5: "如果我丢失手机怎么办？",
    faqA5:
      "你的资金在区块链上，而不是在手机里。在新设备上安装 Kalyx 并用恢复助记词恢复。没有这个助记词，任何人（包括你）都无法访问资金——因此妥善保管它非常重要。",
    faqQ6: "Kalyx 能看到我的助记词吗？",
    faqA6:
      "不能。Kalyx 是非托管的：你的助记词在你的设备上加密，仅在签名时即时解密，然后被遗忘。它绝不会经过我们的服务器。",
    faqQ7: "为什么我必须签署某些交易？",
    faqA7:
      "任何转移资金或授权合约花费资金的操作都必须用你的私钥签名，私钥由你的 PIN 保护。这可以防止网站在未经你明确同意的情况下做任何事情。",
    faqQ8: "如何识别骗局？",
    faqA8:
      "任何正规方都绝不会索要你的恢复助记词。警惕模仿知名品牌的网站（Kalyx 会以红色警示你）、“无限”授权，以及好得不真实的信息。Kalyx 还会在每次签名前显示安全分析（GoPlus）。",
    faqQ9: "为什么我的交易处于待处理状态？",
    faqA9:
      "它正在等待被打包进区块。网络费用过低或严重拥堵会使其变慢。一旦确认，Kalyx 会通知你。",
    faqQ10: "如何取消交易？",
    faqA10:
      "已确认的交易不可逆。仍在待处理的交易有时可以被替换（相同 nonce，更高费用）——此功能在 Kalyx 中尚未自动化。",
    faqQ11: "什么是网络费用？",
    faqA11:
      "这是支付给网络验证者以处理你交易的成本，以原生加密货币（ETH、BNB、POL…）结算。它随网络拥堵情况而变化。",
    faqQ12: "为什么我的交易失败了？",
    faqA12:
      "常见原因：余额不足（含手续费）、兑换时滑点超限、gas 上限过低，或合约拒绝了操作。注意：失败交易的 gas 费仍会被扣除。",
    faqQ13: "如何连接 dApp？",
    faqA13:
      "两种方式：内置浏览器（菜单 → dApp 浏览器），或 WalletConnect（粘贴“wc:…”链接）。两种情况下，你都用 PIN 确认连接。",
    faqQ14: "如何断开 dApp？",
    faqA14:
      "WalletConnect 标签页：对 WalletConnect 会话点“断开”，对内置浏览器网站点“忘记”。",
    faqQ15: "什么是 WalletConnect？",
    faqA15:
      "一种标准协议，通过二维码或链接将你的钱包连接到 dApp，无需浏览器扩展。",
    faqQ16: "如何撤销授权？",
    faqA16:
      "菜单 → 授权：Kalyx 列出你已授权花费代币的合约。撤销你不再使用的（这是一笔交易，需网络费用）。",
    faqQ17: "如何切换网络？",
    faqA17:
      "从主页（网络徽章）或设置 → 网络。同一地址在所有 EVM 网络上通用；仅查询的网络会变化。",
    faqQ18: "如何添加 RPC 网络？",
    faqA18:
      "启用专家模式，然后菜单 → 开发者 → 自定义网络：输入名称、Chain ID、符号和 RPC URL（https）。",
